using System.Data;
using LittleSteps.Api.Data;
using LittleSteps.Api.Domain;
using LittleSteps.Api.Mapping;
using LittleSteps.Api.ViewModels;
using Microsoft.EntityFrameworkCore;
using E=LittleSteps.Api.Data.Entities;
namespace LittleSteps.Api.Services;
public interface IStudentService {Task<object> Search(string? q,int? classId,bool? photoMissing,E.Staff actor);Task<object> Detail(int id,E.Staff actor);Task<object> Save(int? id,StudentRequest request,E.Staff actor);Task Link(int id,GuardianLink request,E.Staff actor);Task Unlink(int id,int guardianId,E.Staff actor);Task Move(int id,TransferRequest request,E.Staff actor);Task<object> History(int id);Task<byte[]?> Photo(int id,E.Staff actor);Task SetPhoto(int id,byte[]? photo,E.Staff actor);}
public sealed class StudentService(AppDbContext db,IAuditService audit,SchoolClock clock):IStudentService
{
 internal IQueryable<E.Student> Query()=>db.Students.Include(s=>s.Class).ThenInclude(c=>c.Teacher).Include(s=>s.StudentGuardians).ThenInclude(l=>l.Guardian).Where(s=>s.IsActive);
 internal static object Summary(E.Student s)=>new{id=s.StudentId,s.StudentCode,fullName=s.FirstName+" "+s.LastName,s.FirstName,s.LastName,s.DateOfBirth,s.Gender,s.ClassId,className=s.Class.Name,teacherName=s.Class.Teacher?.FullName,photoMissing=s.Photo is null,photoUrl=s.Photo is null?null:$"/students/{s.StudentId}/photo",guardianCount=s.StudentGuardians.Count};
 private async Task<E.Student> Find(int id)=>await Query().SingleOrDefaultAsync(s=>s.StudentId==id)??throw new DomainException("Student not found.",404);
 public async Task<object> Search(string? q,int? classId,bool? photoMissing,E.Staff actor){var query=Query().AsNoTracking();if(actor.Role=="SecurityGuard"){if(string.IsNullOrWhiteSpace(q))throw new DomainException("Enter a name or student ID to search.");classId=null;photoMissing=null;}if(!string.IsNullOrWhiteSpace(q))query=query.Where(s=>EF.Functions.ILike(s.FirstName+" "+s.LastName,"%"+q+"%")||EF.Functions.ILike(s.StudentCode!,"%"+q+"%"));if(classId.HasValue)query=query.Where(s=>s.ClassId==classId);if(photoMissing.HasValue)query=query.Where(s=>s.PhotoMissing==photoMissing);return(await query.OrderBy(s=>s.FirstName).ThenBy(s=>s.LastName).Take(500).ToListAsync()).Select(Summary).ToList();}
 public async Task<object> Detail(int id,E.Staff actor){var s=await Find(id);var (start,end)=clock.Day(clock.Today);var mark=await db.AttendanceRecords.SingleOrDefaultAsync(a=>a.StudentId==id&&a.AttendanceDate==clock.Today);var exit=await db.EarlyExits.Where(e=>e.StudentId==id&&e.Authorized&&e.OccurredAt>=start&&e.OccurredAt<end).OrderByDescending(e=>e.OccurredAt).FirstOrDefaultAsync();return new{student=Summary(s),guardians=s.StudentGuardians.Select(g=>new{id=g.GuardianId,g.Guardian.FullName,g.Relationship,emiratesId=actor.Role=="Admin"?g.Guardian.EmiratesId:null,phone=actor.Role=="Admin"?g.Guardian.Phone:null,photoUrl=g.Guardian.Photo is null?null:$"/guardians/{g.GuardianId}/photo"}),status=exit is not null?"Left early":mark?.Status=='P'?"Present":mark?.Status=='A'?"Absent":"Not marked",leftEarlyAt=exit?.OccurredAt,history=actor.Role=="Admin"?await History(id):null};}
 private async Task<E.Guardian> FindGuardian(string id)=>await db.Guardians.SingleOrDefaultAsync(g=>g.EmiratesId==new EmiratesId(id).Value)??throw new DomainException("Register this guardian before linking them.",404);
 public async Task<object> Save(int? id,StudentRequest r,E.Staff actor){
  await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);
  var s=id.HasValue?await Find(id.Value):new E.Student{EnrolYear=(short)clock.Today.Year,IsActive=true,CreatedAt=clock.Now};
  if(id.HasValue && r.ClassId!=s.ClassId)throw new DomainException("Use Class transfer to change class.",409);
  var d=StudentMapper.FromEntity(s);d.Edit(r.FirstName,r.LastName,r.DateOfBirth,r.Gender,clock.Today);
  if(!id.HasValue){var c=await db.Classes.SingleOrDefaultAsync(c=>c.ClassId==r.ClassId)??throw new DomainException("Class not found.",404);var target=new SchoolClass(c.ClassId,c.Name,c.Capacity,await db.Students.CountAsync(s=>s.ClassId==c.ClassId&&s.IsActive));if(!target.HasSpace())throw new DomainException("Class is full.",409);s.ClassId=r.ClassId;d=new Student(0,"",d.FirstName,d.LastName,d.DateOfBirth,d.Gender,r.ClassId,null);d.SetPhoto(r.Photo);}
  else if(r.Photo is not null)d.SetPhoto(r.Photo);
  StudentMapper.Apply(d,s);
  var links=r.Guardians??[];if(links.Length==0)throw new DomainException("Link at least one responsible adult.");if(links.Select(l=>l.EmiratesId).Distinct().Count()!=links.Length)throw new DomainException("A guardian cannot be linked twice.");
  var resolved=new List<(E.Guardian Guardian,string Relationship)>();foreach(var l in links){Rules.Relationship(l.Relationship);resolved.Add((await FindGuardian(l.EmiratesId),l.Relationship));}
  if(!id.HasValue)db.Students.Add(s);else db.StudentGuardians.RemoveRange(s.StudentGuardians);
  await db.SaveChangesAsync();foreach(var l in resolved)db.StudentGuardians.Add(new E.StudentGuardian{StudentId=s.StudentId,GuardianId=l.Guardian.GuardianId,Relationship=l.Relationship});
  if(!id.HasValue)db.ClassTransfers.Add(new E.ClassTransfer{StudentId=s.StudentId,ToClassId=s.ClassId,EffectiveDate=clock.Today,Reason="Enrolment",ByStaffId=actor.StaffId,CreatedAt=clock.Now});
  audit.Record("Students",id.HasValue?"Student edited":"Student enrolled",d.FullName+" ("+s.StudentCode+")",d.PhotoMissing?"Incomplete":"OK",actor);await db.SaveChangesAsync();await tx.CommitAsync();return new{id=s.StudentId,s.StudentCode};
 }
 public async Task Link(int id,GuardianLink r,E.Staff actor){await Find(id);Rules.Relationship(r.Relationship);var g=await FindGuardian(r.EmiratesId);if(await db.StudentGuardians.AnyAsync(l=>l.StudentId==id&&l.GuardianId==g.GuardianId))throw new DomainException("Guardian is already linked.",409);db.StudentGuardians.Add(new E.StudentGuardian{StudentId=id,GuardianId=g.GuardianId,Relationship=r.Relationship});audit.Record("Guardians","Guardian linked",g.FullName+" → student "+id,staff:actor);await db.SaveChangesAsync();}
 public async Task Unlink(int id,int guardianId,E.Staff actor){await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var link=await db.StudentGuardians.SingleOrDefaultAsync(l=>l.StudentId==id&&l.GuardianId==guardianId)??throw new DomainException("Link not found.",404);if(await db.StudentGuardians.CountAsync(l=>l.StudentId==id)<=1)throw new DomainException("Keep at least one responsible adult.",409);db.StudentGuardians.Remove(link);audit.Record("Guardians","Guardian unlinked","Student "+id,staff:actor);await db.SaveChangesAsync();await tx.CommitAsync();}
 public async Task Move(int id,TransferRequest r,E.Staff actor){if(r.EffectiveDate>clock.Today)throw new DomainException("Future transfers are not supported; choose today or a past date.");await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var s=await Find(id);var last=await db.ClassTransfers.Where(t=>t.StudentId==id).MaxAsync(t=>(DateOnly?)t.EffectiveDate);if(last.HasValue&&r.EffectiveDate<last)throw new DomainException("Effective date cannot precede the latest class history entry.");var c=await db.Classes.SingleOrDefaultAsync(c=>c.ClassId==r.ToClassId)??throw new DomainException("Class not found.",404);var d=StudentMapper.FromEntity(s);var transfer=d.MoveToClass(new SchoolClass(c.ClassId,c.Name,c.Capacity,await db.Students.CountAsync(s=>s.ClassId==c.ClassId&&s.IsActive)),r.EffectiveDate,r.Reason);StudentMapper.Apply(d,s);db.ClassTransfers.Add(new E.ClassTransfer{StudentId=id,FromClassId=transfer.FromClassId,ToClassId=transfer.ToClassId,EffectiveDate=transfer.EffectiveDate,Reason=transfer.Reason,ByStaffId=actor.StaffId,CreatedAt=clock.Now});audit.Record("Students","Student moved",d.FullName+" → "+c.Name,staff:actor);await db.SaveChangesAsync();await tx.CommitAsync();}
 public async Task<object> History(int id)=>await db.ClassTransfers.Where(t=>t.StudentId==id).OrderByDescending(t=>t.EffectiveDate).ThenByDescending(t=>t.TransferId).Select(t=>new{t.TransferId,fromClass=t.FromClass!=null?t.FromClass.Name:null,toClass=t.ToClass.Name,t.EffectiveDate,t.Reason,by=t.ByStaff.FullName}).ToListAsync();
 public async Task<byte[]?> Photo(int id,E.Staff actor){var s=await Find(id);if(actor.Role=="Teacher" && actor.Class?.ClassId!=s.ClassId)throw new DomainException("This student is not in your class.",403);return s.Photo;}
 public async Task SetPhoto(int id,byte[]? photo,E.Staff actor){var s=await Find(id);var d=StudentMapper.FromEntity(s);d.SetPhoto(photo);StudentMapper.Apply(d,s);audit.Record("Students",photo is null?"Photo removed":"Photo added",d.FullName,photo is null?"Incomplete":"OK",actor);await db.SaveChangesAsync();}
}
